def make_genai_metric(
    name: str,
    definition: str,
    grading_prompt: str,
    examples: list[EvaluationExample] | None = None,
    version: str | None = _get_latest_metric_version(),
    model: str | None = _get_default_model(),
    grading_context_columns: str | list[str] | None = None,
    include_input: bool = True,
    parameters: dict[str, Any] | None = None,
    aggregations: list[str] | None = None,
    greater_is_better: bool = True,
    max_workers: int = 10,
    metric_metadata: dict[str, Any] | None = None,
    extra_headers: dict[str, str] | None = None,
    proxy_url: str | None = None,
) -> EvaluationMetric:
    original_grading_context_columns = grading_context_columns
    aggregations = _validate_aggregations(aggregations)
    if isinstance(grading_context_columns, str):
        grading_context_columns = [grading_context_columns]
    elif not grading_context_columns:
        grading_context_columns = []
    elif not isinstance(grading_context_columns, list) or not all(
        isinstance(column, str) for column in grading_context_columns
    ):
        raise MlflowException(
            "`grading_context_columns` must be a string or a list of strings.",
            error_code=INVALID_PARAMETER_VALUE,
        )

    normalized_examples = []
    for example in examples or []:
        context = example.grading_context
        if isinstance(context, str):
            # Preserve the historical IndexError when there is no column to
            # associate with a scalar grading context.
            context = {grading_context_columns[0]: context}
        elif context is None:
            context = {}
        elif not isinstance(context, dict):
            raise MlflowException(
                "Example grading context must be a dictionary or a string.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if set(context) != set(grading_context_columns):
            raise MlflowException(
                "The grading context columns in each example must exactly match "
                f"{grading_context_columns}. Found: {list(context)}",
                error_code=INVALID_PARAMETER_VALUE,
            )
        normalized_examples.append(
            replace(
                example,
                input=example.input if include_input else None,
                grading_context=context or None,
            )
        )

    class_name = f"mlflow.metrics.genai.prompts.{version}.EvaluationModel"
    try:
        evaluation_model_class = _get_class_from_string(class_name)
        evaluation_model_kwargs = {
            "name": name,
            "definition": definition,
            "grading_prompt": grading_prompt,
            "examples": normalized_examples,
            "include_input": include_input,
        }
        if model is not None:
            evaluation_model_kwargs["model"] = model
        if parameters is not None:
            evaluation_model_kwargs["parameters"] = parameters
        evaluation_model = evaluation_model_class(
            **evaluation_model_kwargs
